SELECT COUNT(*) AS Vocalists FROM singer;
SELECT COUNT(*) AS total_musicians FROM singer;
SELECT Name, Nationality, Age FROM singer ORDER BY Age DESC, Name;
SELECT Name, Country, Age FROM singer ORDER BY Age DESC;
