SELECT singer.Name, singer.Song_release_year FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID INNER JOIN stadium ON concert.Stadium_ID = stadium.Stadium_ID WHERE singer.Age < (SELECT MIN(Singer.Age) FROM singer);
SELECT singer.Name, concert.Year AS publish_year FROM singer INNER JOIN concert ON singer.Singer_ID = concert.Singer_ID WHERE singer.Age < (SELECT MAX(Age) FROM singer)
SELECT DISTINCT Country FROM singer WHERE Age > 20;
SELECT DISTINCT Country FROM singer WHERE Age > 20;
SELECT singer.Country, COUNT(singer_in_concert.Singer_ID) AS number_of_vocalists FROM singer JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID GROUP BY singer.Country
SELECT DISTINCT State, COUNT(*) AS Total_Musicians FROM singer GROUP BY State;
SELECT singer.Name AS Name, singer.Age AS Age, singer.Country AS Country, singer_in_concert.Song_Name AS Song_Name FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID WHERE singer_in_concert.concert.Year = (SELECT AVG(Song_release_year) FROM concert GROUP BY concert.Year) AND singer.Age > (SELECT AVG(Singer.Age) FROM singer GROUP BY Singer.Age)
SELECT s.Name, c.Theme AS Concert_Title, s.Age AS Age FROM singer s JOIN concert c ON s.Singer_ID = c.Singer_ID WHERE s.Age > (SELECT AVG(Age) FROM singer)
SELECT stadium.Stadium_ID, singer.Name, concert.Year FROM concert JOIN singer ON concert.Singer_ID = singer.Singer_ID JOIN stadium ON concert.Stadium_ID = stadium.Stadium_ID WHERE concert.Year BETWEEN 2020 AND 2025;
SELECT singer.Name, concert.Stadium_ID FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID WHERE concert.Year BETWEEN 2020 AND 2025 AND concert.Stadium_ID = stadium.Stadium_ID AND singer_in_concert.capacity >= 5000 AND singer_in_concert.capacity <= 10000;
SELECT AVG(Capacity), MAX(Capacity) FROM stadium;
SELECT AVG(Capacity) AS Average, MAX(Capacity) AS Maximum FROM stadium;
SELECT Name, AVG(Average) AS Average_Average FROM stadium INNER JOIN singer_in_concert ON stadium.Stadium_ID = singer_in_concert.concert_ID GROUP BY Name ORDER BY AVG(Average) DESC LIMIT 1;
SELECT Name, Capacity FROM stadium WHERE Average = (SELECT AVG(Average) FROM stadium ORDER BY Average DESC LIMIT 1)
