SELECT COUNT(*) AS total_shows_per_stadium FROM concert JOIN singer_in_concert ON concert.concert_ID = singer_in_concert.concert_ID JOIN stadium ON singer_in_concert.Stadium_ID = stadium.Stadium_ID;
