SELECT concert.Year, COUNT(singer_in_concert.Singer_ID) AS Show_Count FROM concert JOIN singer_in_concert ON concert.concert_ID = singer_in_concert.concert_ID GROUP BY concert.Year ORDER BY Show_Count DESC LIMIT 1;
SELECT concert.Year, COUNT(singer_in_concert.Singer_ID) AS total_shows FROM concert JOIN singer_in_concert ON concert.concert_ID = singer_in_concert.concert_ID GROUP BY concert.Year ORDER BY total_shows DESC;
