SELECT COUNT(*) FROM visitor WHERE Age < 30
SELECT v.Name FROM visitor v JOIN visit v_visit ON v.ID = v_visit.visitor_ID WHERE v.Level_of_membership > 4 ORDER BY v.Level_of_membership DESC;
SELECT AVG(visitor.Age) FROM visitor WHERE visitor.Level_of_membership <= 4
SELECT visitor.Name, visitor.Level_of_membership FROM visitor JOIN visit ON visit.visitor_ID = visitor.ID WHERE visitor.Level_of_membership > 4 ORDER BY visitor.Age ASC;
SELECT museum.Museum_ID, museum.Name, COUNT(visitor.ID) AS total_visitors FROM museum JOIN visit ON museum.Museum_ID = visit.Museum_ID JOIN visitor ON visit.visitor_ID = visitor.ID GROUP BY museum.Museum_ID ORDER BY total_visitors DESC LIMIT 1;
SELECT AVG(visit.Total_spent) FROM visit INNER JOIN museum ON visit.Museum_ID = museum.Museum_ID WHERE museum.Open_Year < '2009'
SELECT museum.Open_Year, visitor.Worker_Number FROM museum INNER JOIN visitor ON museum.Museum_ID = visitor.Museum_ID;
SELECT Name FROM museum WHERE Num_of_Staff > (SELECT MIN(Num_of_Staff) FROM visit WHERE Open_Year > '2010')
SELECT v.ID, v.Name, v.Age FROM visitor v JOIN visit v2 ON v.ID = v2.visitor_ID JOIN museum m ON v2.Museum_ID = m.Museum_ID WHERE v2.Num_of_Ticket > 0;
SELECT id, name, membership_level FROM visitor JOIN visit ON visit.visitor_ID = visitor.ID JOIN museum ON visit.Museum_ID = museum.Museum_ID WHERE visit.Total_spent > (SELECT AVG(Total_spent) FROM visit)
SELECT museum.Museum_ID, museum.Name, COUNT(visit.Num_of_Ticket) AS Num_of_visits FROM museum INNER JOIN visit ON museum.Museum_ID = visit.Museum_ID GROUP BY museum.Museum_ID, museum.Name ORDER BY Num_of_visits DESC;
SELECT museum.Name FROM museum JOIN visit ON museum.Museum_ID = visit.Museum_ID WHERE visit.visitor_ID IS NULL
SELECT v.Name, v.Age FROM visitor v JOIN visit v2 ON v.ID = v2.visitor_ID JOIN museum m ON v2.Museum_ID = m.Museum_ID GROUP BY v.Name, v.Age ORDER BY v.Age DESC;
SELECT AVG(visit.Num_of_Ticket) AS average_tickets, MAX(visit.Num_of_Ticket) AS maximum_tickets FROM visit INNER JOIN museum ON visit.Museum_ID = museum.Museum_ID;
SELECT SUM(visit.Total_spent) FROM visit INNER JOIN museum ON visit.Museum_ID = museum.Museum_ID WHERE visitor.Level_of_membership = '1' AND visit.visitor_ID IN (SELECT ID FROM visitor WHERE Level_of_membership = '1')
SELECT v.Name FROM visitor v JOIN visit v2 ON v.ID = v2.visitor_ID JOIN museum m ON v2.Museum_ID = m.Museum_ID WHERE m.Open_Year < 2009 AND m.Open_Year > 2011;
SELECT COUNT(*) FROM visit WHERE Open_Year < '2010' AND Museum_ID IS NOT NULL;
