SELECT rankings.ranking, players.player_id, players.first_name, players.last_name, players.hand, players.birth_date, players.country_code, matches.loser_rank, matches.loser_rank_points, matches.loser_seed, matches.round, matches.minute, matches.rounds, matches.score, matches.surface, matches.tourney_date, matches.tourney_id, matches.tourney_level, matches.tourney_name, matches.winner_rank, matches.winner_rank_points, matches.winner_seed, matches.year FROM rankings JOIN players ON rankings.player_id = players.player_id JOIN matches ON rankings.player_id = matches.loser_id;
SELECT DISTINCT COUNT(DISTINCT players.country_code) FROM players;
SELECT COUNT(DISTINCT players.country_code) FROM players;
SELECT DISTINCT first_name FROM players;
SELECT COUNT(DISTINCT loser_name) FROM players JOIN matches ON matches.loser_id = players.player_id
SELECT tourney_name FROM matches INNER JOIN rankings ON matches.loser_id = rankings.player_id WHERE matches.round = 1 AND matches.round_points > 10;
SELECT tourney_name FROM matches JOIN rankings ON matches.loser_id = rankings.player_id WHERE match_num > 10;
SELECT p.first_name, p.last_name FROM players p JOIN matches m ON p.player_id = m.winner_id WHERE m.year IN ('2013', '2016')
SELECT p.first_name, p.last_name FROM players p JOIN matches m ON p.player_id = m.winner_id WHERE m.year IN (2013, 2016) AND p.first_name != 'NULL' AND p.last_name != 'NULL' AND p.hand IS NOT NULL;
SELECT COUNT(*) FROM matches WHERE year IN (2013, 2016)
SELECT COUNT(*) FROM matches WHERE year IN ('2013', '2016')
SELECT players.first_name, players.last_name, matches.winner_name FROM players INNER JOIN matches ON players.player_id = matches.winner_id INNER JOIN rankings ON matches.tourney_id = rankings.tourney_id WHERE matches.tourney_name IN ('WTA Championships', 'Australian Open')
SELECT p.first_name, p.country_code FROM players p JOIN matches m ON p.player_id = m.winner_id JOIN rankings r ON p.player_id = r.player_id WHERE m.tourney_name = 'WTA Championships' AND m.tourney_name = 'Australian Open'
SELECT players.first_name, players.country_code AS state_abbreviation FROM players JOIN rankings ON players.player_id = rankings.player_id WHERE rankings.ranking_points = (SELECT MAX(ranking_points) FROM rankings)
SELECT p.first_name, p.country_code FROM players p JOIN rankings r ON p.player_id = r.player_id ORDER BY r.ranking DESC LIMIT 1;
SELECT players.first_name, players.last_name, matches.loser_name FROM players JOIN matches ON players.player_id = matches.loser_id ORDER BY players.birth_date;
SELECT p.first_name, p.last_name, p.birth_date FROM players p ORDER BY p.birth_date;
SELECT players.first_name, players.last_name, players.hand, players.birth_date FROM players INNER JOIN matches ON players.player_id = matches.loser_id ORDER BY players.birth_date;
SELECT players.first_name, players.last_name, players.hand, players.birth_date FROM players ORDER BY players.birth_date
SELECT players.first_name, players.country_code, matches.tourney_name, matches.tourney_level FROM players JOIN matches ON players.player_id = matches.winner_id JOIN rankings ON players.player_id = rankings.player_id GROUP BY players.first_name, players.country_code, matches.tourney_name, matches.tourney_level ORDER BY matches.tourney_level DESC;
SELECT p.first_name, p.country_code, m.tourney_name, m.tourney_level FROM players p JOIN matches m ON p.player_id = m.loser_id WHERE m.tourney_name = (SELECT tourney_name FROM rankings r WHERE r.ranking = (SELECT MAX(ranking_points) FROM rankings r)) ORDER BY p.country_code DESC;
SELECT MAX(year) FROM matches;
SELECT year, COUNT(*) AS num_competitions FROM matches GROUP BY year ORDER BY num_competitions DESC;
SELECT p.first_name, p.rankings.ranking_points AS rank_points FROM players p JOIN rankings r ON p.player_id = r.player_id ORDER BY r.rankings.ranking_points DESC LIMIT 1;
SELECT p.first_name, p.last_name, m.round, m.round_points, m.round_rank_points, m.round_rank FROM players p JOIN matches m ON p.player_id = m.loser_id WHERE m.round_points = (SELECT MAX(m.round_points) FROM matches m WHERE m.round_points = m.round_points)
SELECT winner_name FROM matches INNER JOIN players ON matches.winner_id = players.player_id WHERE matches.tourney_id = (SELECT tourney_id FROM rankings WHERE rankings.ranking = (SELECT MAX(ranking_points) FROM rankings))
SELECT winner_name FROM matches JOIN players ON matches.winner_id = players.player_id WHERE matches.tourney_id = (SELECT tourney_id FROM rankings WHERE ranking = (SELECT ranking FROM rankings WHERE player_id = (SELECT player_id FROM players WHERE first_name = 'John' AND last_name = 'Doe' AND country_code = 'AU')) AND ranking_points = (SELECT ranking_points FROM rankings WHERE player_id = (SELECT player_id FROM players WHERE first_name = 'John' AND last_name = 'Doe' AND country_code = 'AU')) ORDER BY winner_rank_points DESC LIMIT 1;
SELECT players.first_name, players.last_name FROM players JOIN matches ON players.player_id = matches.loser_id JOIN rankings ON players.player_id = rankings.player_id WHERE matches.minutes > (SELECT MAX(minutes) FROM matches) ORDER BY players.first_name, players.last_name;
SELECT players.first_name, players.last_name FROM players JOIN matches ON matches.loser_id = players.player_id ORDER BY matches.round DESC LIMIT 1;
SELECT players.first_name, AVG(rankings.ranking_points) AS average_ranking_points FROM players JOIN rankings ON players.player_id = rankings.player_id GROUP BY players.first_name
SELECT p.first_name, p.last_name, AVG(r.rankings_points) AS average_rankings_points FROM players p JOIN rankings r ON p.player_id = r.player_id GROUP BY p.player_id
SELECT players.first_name, players.last_name, SUM(ranking_points) AS total_ranking_points FROM players JOIN rankings ON players.player_id = rankings.player_id GROUP BY players.first_name, players.last_name
SELECT p.first_name, p.last_name, r.ranking_points FROM players p JOIN rankings r ON p.player_id = r.player_id;
SELECT COUNT(DISTINCT players.country_code) AS count FROM players;
SELECT COUNT(DISTINCT players.country_code) AS total_participants, players.country_code AS state FROM players JOIN rankings ON rankings.player_id = players.player_id GROUP BY players.country_code
SELECT players.country_code FROM players JOIN rankings ON players.player_id = rankings.player_id GROUP BY players.country_code ORDER BY rankings.ranking_points DESC LIMIT 1;
