SELECT country_code FROM players JOIN matches ON players.player_id = matches.loser_id WHERE matches.round = '2' AND matches.minutes > 5000
SELECT country_code FROM players JOIN matches ON players.player_id = matches.loser_id WHERE matches.round = 1 AND matches.round_points > 50
SELECT DISTINCT players.player_id, COUNT(ranking.points) AS total_trips FROM rankings INNER JOIN players ON rankings.player_id = players.player_id GROUP BY players.player_id;
