SELECT COUNT(*) FROM players INNER JOIN matches ON players.player_id = matches.winner_id WHERE players.hand = 'left' AND matches.tourney_id = rankings.tourney_id
SELECT p.first_name, p.last_name, m.rank_points AS rank_points, m.round, m.year FROM players p JOIN matches m ON p.player_id = m.winner_id JOIN rankings r ON m.player_id = r.player_id WHERE r.ranking_points ORDER BY r.ranking_points DESC;
SELECT p.first_name, p.country_code, m.loser_rank_points AS winner_rank_points FROM players p JOIN matches m ON p.player_id = m.loser_id ORDER BY winner_rank_points DESC LIMIT 1;
SELECT COUNT(*) AS number_of_participants FROM players;
SELECT hand, COUNT(*) AS participant_count FROM players JOIN matches ON players.player_id = matches.loser_id GROUP BY hand
SELECT COUNT(*) FROM ship WHERE disposition_of_ship = 'Captured'
SELECT name, tonnage FROM battle JOIN ship ON battle.id = ship.lost_in_battle ORDER BY name DESC
SELECT battle.name, battle.date, battle.result FROM battle JOIN ship ON battle.id = ship.lost_in_battle;
SELECT MAX(result), MIN(result) FROM battle JOIN ship ON ship.lost_in_battle = battle.id;
SELECT AVG(death.injured) AS average_injuries_per_time FROM death INNER JOIN ship ON death.caused_by_ship_id = ship.id INNER JOIN battle ON ship.lost_in_battle = battle.id;
SELECT death.killed, death.injured, ship.name, ship.tonnage FROM ship INNER JOIN battle ON ship.id = battle.id INNER JOIN death ON ship.lost_in_battle = death.caused_by_ship_id WHERE ship.tonnage = 't'
SELECT battle.name, battle.result FROM battle JOIN ship ON battle.id = ship.lost_in_battle WHERE battle.bulgarian_commander != 'Boril'
SELECT battle.id, name, bulgarian_commander, latin_commander, result FROM battle JOIN ship ON battle.id = ship.lost_in_battle JOIN death ON ship.id = death.caused_by_ship WHERE ship_type = 'Brig' AND result = 'lost';
SELECT battle.id, battle.name, death.killed, death.injured FROM battle JOIN ship ON battle.id = ship.lost_in_battle JOIN death ON ship.id = death.caused_by_ship WHERE death.killed > 10 OR death.injured > 10
SELECT ship.id, ship.name, battle.id, battle.name, ship.lost_in_battle, ship.tonnage, ship.ship_type, ship.location, ship.disposition_of_ship FROM ship JOIN battle ON ship.lost_in_battle = battle.id JOIN death ON ship.id = death.caused_by_ship_id GROUP BY ship.id, ship.name, battle.id, battle.name, ship.lost_in_battle, ship.tonnage, ship.ship_type, ship.location, ship.disposition_of_ship ORDER BY ship.id ASC;
SELECT DISTINCT name FROM battle WHERE bulgarian_commander = 'Kaloyan' AND latin_commander = 'Baldwin I'
SELECT COUNT(DISTINCT battle.id) FROM battle;
SELECT COUNT(DISTINCT battle.id) FROM battle WHERE battle.id NOT IN (SELECT ship.id FROM ship WHERE ship.tonnage = 225)
SELECT battle.name, battle.date, ship.name, death.note FROM battle INNER JOIN ship ON battle.id = ship.lost_in_battle INNER JOIN death ON ship.id = death.caused_by_ship WHERE battle.name = 'Lettice' OR battle.name = 'HMS Atalanta' AND ship.name = 'Lettice' OR ship.name = 'HMS Atalanta' AND death.note IS NOT NULL;
SELECT battle.name, battle.result, battle.bulgarian_commander FROM battle JOIN ship ON battle.id = ship.lost_in_battle WHERE ship.location = 'English Channel' AND ship.disposition_of_ship = 'lost';
SELECT note FROM death WHERE date LIKE '%East%'
SELECT Addresses.address_id, Addresses.line_1, Addresses.line_2 FROM Addresses;
SELECT line_1, line_2 FROM Addresses ORDER BY line_1 LIMIT 2;
SELECT COUNT(*) FROM Courses;
SELECT COUNT(*) FROM Courses;
SELECT course_description, degree_summary_description FROM Degree_Programs INNER JOIN Degree_Programs ON Degree_Programs.degree_program_id = Degree_Programs.degree_program_id;
SELECT course_description, course_name FROM Courses;
SELECT zip_postcode FROM Addresses WHERE city = 'Port Chelsea'
SELECT zip_postcode FROM Addresses WHERE city = 'Port Chelsea';
SELECT D.department_name, D.department_id FROM Departments D JOIN Degree_Programs D2 ON D.department_id = D2.department_id ORDER BY D2.department_id DESC;
SELECT D.department_name, COUNT(D.*) AS count_of_degrees_per_division FROM Departments D JOIN Degree_Programs DP ON D.department_id = DP.department_id GROUP BY D.department_id, D.department_name ORDER BY count_of_degrees_per_division DESC;
SELECT COUNT(*) FROM Departments
SELECT COUNT(DISTINCT department_id) FROM Departments
SELECT DISTINCT COUNT(DISTINCT course_name) FROM Courses;
SELECT COUNT(DISTINCT degree_program_id) FROM Degree_Programs;
SELECT COUNT(DISTINCT student_id) FROM Students;
SELECT COUNT(*) FROM Departments
SELECT course_name, section_description FROM Sections INNER JOIN Courses ON Sections.course_id = Courses.course_id;
SELECT course_name, section_description FROM Courses JOIN Sections ON Courses.course_id = Sections.course_id JOIN Departments ON Sections.department_id = Departments.department_id JOIN Degree_Programs ON Degree_Programs.department_id = Departments.department_id WHERE Sections.section_name IS NOT NULL;
SELECT course_name, course_id FROM Courses INNER JOIN Sections ON Sections.course_id = Courses.course_id WHERE Sections.section_count <= 2;
{ "sql": "SELECT DISTINCT course_name, course_id FROM Courses INNER JOIN Sections ON Sections.course_id = Courses.course_id WHERE Sections.section_description LIKE '%2%'"; }
SELECT section_name FROM Sections ORDER BY section_name DESC;
SELECT section_name FROM Sections ORDER BY section_name DESC;
SELECT S.first_name, S.student_id FROM Students S JOIN Student_Enrolment_Courses SC ON S.student_id = SC.student_course_id JOIN Courses C ON SC.course_id = C.course_id JOIN Sections S2 ON C.course_id = S2.course_id JOIN Semesters S3 ON S2.semester_id = S3.semester_id WHERE S.first_name = (SELECT MAX(first_name) FROM Students) ORDER BY S.student_id;
SELECT s.student_id, d.department_name, s.first_name, s.middle_name, s.last_name, s.cell_mobile_number, s.email_address, s.ssn, s.date_first_registered, s.date_left, s.other_student_details FROM Students s JOIN Departments d ON s.department_id = d.department_id JOIN Degree_Programs dp ON d.department_id = dp.department_id JOIN Sections s_sec ON s.section_id = s_sec.section_id JOIN Courses c ON s_sec.course_id = c.course_id JOIN Student_Enrolment se ON s.student_id = se.student_id JOIN Student_Enrolment_Courses sc ON se.student_enrolment_id = sc.student_enrolment_id JOIN Courses c ON sc.course_id = c.course_id WHERE s.date_first_registered IS NOT NULL AND s.date_left IS NOT NULL ORDER BY s.date_first_registered DESC LIMIT 1;
SELECT course_description, other_details FROM Courses JOIN Sections ON Courses.course_id = Sections.course_id WHERE section_name LIKE '%computer%';
SELECT DISTINCT t.transcript_date, t.transcript_contents.transcript_id, t.transcript_contents.student_course_id, t.transcript_contents.student_id, t.transcript_contents.section_name, t.transcript_contents.section_description, t.transcript_contents.degree_program_id, t.transcript_contents.degree_summary_name, t.transcript_contents.degree_summary_description FROM Transcript_Contents t JOIN Student_Enrolment_Courses s ON t.student_course_id = s.student_course_id JOIN Courses c ON s.course_id = c.course_id JOIN Sections s2 ON s.course_id = s2.section_id JOIN Departments d ON s2.department_id = d.department_id JOIN Degree_Programs dp ON dp.department_id = d.department_id JOIN Students s1 ON s1.student_id = s.student_id JOIN Addresses a ON s1.current_address_id = a.address_id JOIN Transcripts t ON t.transcript_id = s1.student_id WHERE t.transcript_contents.student_course_id IN (SELECT student_course_id FROM Student_Enrolment_Courses WHERE course_id IN (SELECT course_id FROM Courses WHERE course_name LIKE 'Computer%' AND course_description LIKE '%Computer%'));
SELECT s.first_name, s.middle_name, s.last_name, s.student_id FROM Students s JOIN Student_Enrolment_Courses sc ON s.student_id = sc.student_course_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections ssec ON sc.course_id = ssec.course_id JOIN Semesters ssem ON ssec.semester_id = ssem.semester_id JOIN Degree_Programs dp ON dp.degree_program_id = ssec.degree_program_id JOIN Departments d ON dp.department_id = d.department_id;
SELECT S.middle_name, S.family_name, S.student_id, D.department_id, D.department_name FROM Students S JOIN Degree_Programs D ON S.student_id = D.degree_program_id WHERE D.degree_summary_name = '2 degree programs'
SELECT first_name, middle_name, last_name, other_address_details FROM Students WHERE first_name OR middle_name OR last_name OR other_address_details IS NOT NULL;
SELECT middle_name, family_name, first_name FROM Students ORDER BY first_name, middle_name, family_name;
SELECT DISTINCT Degree_Programs.degree_summary_name AS program_name, COUNT(Sections.section_name) AS student_count FROM Degree_Programs INNER JOIN Sections ON Degree_Programs.degree_program_id = Sections.course_id GROUP BY Degree_Programs.degree_program_id ORDER BY student_count DESC;
SELECT DISTINCT degree_program_id, degree_summary_name FROM Degree_Programs WHERE degree_summary_description IS NULL ORDER BY degree_summary_name DESC;
{ "sql": "SELECT D.degree_program_id, S.first_name, S.last_name, D.degree_summary_name, D.degree_summary_description\nFROM Degree_Programs D\nJOIN Students S ON D.department_id = S.department_id\nJOIN Sections S2 ON D.degree_program_id = S2.course_id\nJOIN Courses C ON S2.course_id = C.course_id\nJOIN Student_Enrolment_Courses SC ON S2.course_id = SC.course_id\nJOIN Courses C2 ON SC.course_id = C2.course_id\nJOIN Transcripts T ON SC.transcript_id = T.transcript_id\nJOIN Transcript_Contents TC ON TC.student_course_id = SC.student_course_id\nJOIN Courses C3 ON TC.transcript_id = C3.transcript_id\nJOIN Transcripts T2 ON T2.transcript_id = C3.transcript_id\nJOIN Student_Enrolment_Courses SC2 ON SC2.student_course_id = C3.student_course_id\nJOIN Student_Enrolment_Courses SC3 ON SC3.student_course_id = C2.student_course_id\nJOIN Courses C4 ON SC3.course_id = C4.course_id\nJOIN Transcripts T3 ON T3.transcript_id = C4.transcript_id\nJOIN Transcript_Contents TC3 ON TC3.student_course_id = C4.student_course_id\nJOIN Courses C5 ON TC3.transcript_id = C5.transcript_id\nJOIN Transcripts T4 ON T4.transcript_id = C5.transcript_id\nJOIN Student_Enrolment_Courses SC4 ON SC4.student_course_id = C5.student_course_id\nJOIN Student_Enrolment_Courses SC5 ON SC5.student_course_id = C6.student_course_id\nJOIN Courses C6 ON SC5.course_id = C6.course_id\nJOIN Transcripts T5 ON T5.transcript_id = C6.transcript_id\nJOIN Transcript_Contents TC5 ON TC5.student_course_id = C6.student_course_id\nJOIN Courses C7 ON TC5.transcript_id = C7.transcript_id\nJOIN Transcripts T6 ON T6.transcript_id = C7.transcript_id\nJOIN Student_Enrolment_Courses SC6 ON SC6.student_course_id = C7.student_course_id\nJOIN Student_Enrolment_Courses SC7 ON SC7.student_course_id = C8.student_course_id\nJOIN Courses C8 ON SC7.course_id = C8.course_id\nJOIN Transcripts T7 ON T7.transcript_id = C8.transcript_id\nJOIN Transcript_Contents TC7 ON TC7.student_course_id = C8.student_course_id\nJOIN Courses C9 ON TC7.transcript_id = C9.transcript_id\nJOIN Transcripts T8 ON T8.transcript_id = C9.transcript_id\nJOIN Student_Enrolment_Courses SC8 ON SC8.student_course_id = C9.student_course_id\nJOIN Student_Enrolment_Courses SC9 ON SC9.student_course_id = C10.student_course_id\nJOIN Courses C10 ON SC9.course_id = C10.course_id\nJOIN Transcripts T9 ON T9.transcript_id = C10.transcript_id\nJOIN Transcript_Contents TC9 ON TC9.student_course_id = C10.student_course_id\nJOIN Courses C11 ON TC9.transcript_id = C11.transcript_id\nJOIN Transcripts T10 ON T10.transcript_id = C11.transcript_id\nJOIN Student_Enrolment_Courses SC10 ON SC10.student_course_id = C11.student_course_id\nJOIN Student_Enrolment_Courses SC11 ON SC1
SELECT D.degree_program_id, D.degree_summary_name, D.degree_summary_description FROM Degree_Programs D JOIN Students S ON D.department_id = S.department_id JOIN Degree_Programs D2 ON D2.degree_program_id = D.degree_program_id WHERE D.degree_summary_name IS NOT NULL AND D.degree_summary_description IS NOT NULL ORDER BY D.degree_program_id DESC
SELECT s.id, s.first_name, s.middle_name, s.last_name, s.student_id, COUNT(CASE WHEN s.student_id = e.student_id THEN 1 END) AS enrollments, e.semester_id FROM Students s JOIN Student_Enrolment e ON s.student_id = e.student_id JOIN Student_Enrolment_Courses sc ON e.student_enrolment_id = sc.student_enrolment_id JOIN Courses c ON sc.course_id = c.course_id JOIN Departments d ON e.degree_program_id = d.department_id JOIN Degree_Programs dp ON e.degree_program_id = dp.degree_program_id JOIN Semesters ssem ON e.semester_id = ssem.semester_id GROUP BY s.id, s.first_name, s.middle_name, s.last_name, s.student_id, e.semester_id ORDER BY enrollments DESC;
SELECT s.middle_name, s.id, COUNT(s.student_id) AS enrollments FROM Students s JOIN Student_Enrolment_Courses sc ON s.student_id = sc.student_course_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections ssec ON ssec.section_id = s.section_id JOIN Semesters ssem ON ssem.semester_id = s.section_id GROUP BY s.middle_name, s.id ORDER BY enrollments DESC;
SELECT section_name FROM Sections WHERE section_description IS NULL;
SELECT s.first_name, s.last_name FROM Students s JOIN Addresses a ON s.current_address_id = a.address_id WHERE s.date_left IS NULL;
SELECT course_name FROM Courses WHERE course_description IS NULL OR course_description = '';
SELECT course_name FROM Courses WHERE course_description IS NULL;
SELECT course_name FROM Courses JOIN Student_Enrolment_Courses ON Courses.course_id = Student_Enrolment_Courses.course_id JOIN Student_Enrolment ON Student_Enrolment_Courses.student_enrolment_id = Student_Enrolment.student_id GROUP BY course_name ORDER BY COUNT(*) DESC LIMIT 1;
SELECT course_name, COUNT(*) AS student_count FROM Courses INNER JOIN Student_Enrolment_Courses ON Courses.course_id = Student_Enrolment_Courses.course_id GROUP BY course_name ORDER BY student_count DESC LIMIT 1;
SELECT S.last_name, S.current_address_id, S.state_province_county, S.state FROM Addresses S JOIN Students S ON S.address_id = S.current_address_id JOIN Student_Enrolment_Courses SC ON S.student_id = SC.student_course_id JOIN Courses C ON SC.course_id = C.course_id JOIN Sections S1 ON S1.section_id = S.section_id JOIN Semesters S2 ON S2.semester_id = S.section_id JOIN Departments D ON D.department_id = S1.department_id JOIN Degree_Programs DP ON DP.department_id = D.department_id WHERE S.state_province_county = 'North Carolina' AND S.state_province_county = 'North Carolina' AND NOT EXISTS (SELECT 1 FROM Student_Enrolment_Courses SC WHERE SC.student_course_id = S.student_id AND SC.degree_program_id = DP.degree_program_id)
SELECT s.last_name, s.permanent_address_id, s.current_address_id, s.first_name, s.middle_name, s.last_name, s.cell_mobile_number, s.email_address, s.ssn, s.date_first_registered, s.date_left, s.other_student_details FROM Addresses s JOIN Students student ON s.address_id = student.current_address_id WHERE s.state_province_county = 'North Carolina' AND s.state_province_county != 'North Carolina' ORDER BY s.last_name
SELECT S.student_id, S.date_first_registered, S.date_left, S.first_name, S.middle_name, S.last_name, S.cell_mobile_number, S.email_address, S.ssn, S.date_first_registered, S.date_left FROM Students S WHERE S.date_first_registered > S.date_left AND S.date_first_registered IS NOT NULL AND S.date_left IS NOT NULL LIMIT 10;
SELECT student_id, date_first_registered, date_left FROM Students INNER JOIN Student_Enrolment_Courses ON Students.student_id = Student_Enrolment_Courses.student_enrolment_id INNER JOIN Courses ON Student_Enrolment_Courses.course_id = Courses.course_id INNER JOIN Sections ON Student_Enrolment_Courses.course_id = Sections.course_id INNER JOIN Departments ON Student_Enrolment_Courses.course_id = Departments.department_id INNER JOIN Degree_Programs ON Student_Enrolment_Courses.course_id = Degree_Programs.department_id WHERE (SELECT COUNT(*) FROM Courses) >= 2;
SELECT s.last_name, s.cell_mobile_number FROM Students s WHERE s.first_name = 'Timmothy' AND s.last_name = 'Ward';
SELECT student_id, first_name, last_name, cell_mobile_number FROM Students WHERE first_name = 'Timothy' AND last_name = 'Ward';
SELECT s.first_name, s.middle_name, s.last_name, s.date_first_registered, s.date_left FROM Students s WHERE s.date_first_registered IS NULL OR s.date_left IS NULL ORDER BY s.date_first_registered ASC;
SELECT s.middle_name, s.family_name, s.first_name FROM Students s JOIN Addresses a ON s.current_address_id = a.address_id;
SELECT students.first_name, students.middle_name, students.last_name, students.date_first_registered, students.date_left FROM Students JOIN Addresses ON Addresses.address_id = Students.current_address_id JOIN Courses ON Courses.course_id = Students.current_address_id JOIN Departments ON Departments.department_id = Students.department_id JOIN Degree_Programs ON Degree_Programs.department_id = Departments.department_id JOIN Sections ON Sections.course_id = Courses.course_id JOIN Student_Enrolment_Courses ON Student_Enrolment_Courses.course_id = Sections.course_id JOIN Student_Enrolment ON Student_Enrolment.student_id = Student_Enrolment_Courses.student_enrolment_id JOIN Transcripts ON Transcripts.transcript_id = Student_Enrolment_Courses.transcript_id JOIN Transcript_Contents ON Transcript_Contents.transcript_id = Transcripts.transcript_id WHERE students.date_first_registered IS NULL OR students.date_left IS NULL ORDER BY students.date_first_registered ASC;
SELECT s.middle_name, s.family_name, s.first_name FROM Students s JOIN Addresses a ON s.current_address_id = a.address_id JOIN Transcripts t ON s.student_id = t.student_id JOIN Transcript_Contents tc ON t.transcript_id = tc.transcript_id JOIN Sections ssec ON ssec.section_id = t.section_id JOIN Courses c ON ssec.course_id = c.course_id JOIN Departments d ON c.department_id = d.department_id JOIN Degree_Programs dp ON c.department_id = dp.department_id;
SELECT s.first_name, s.permanent_address_id, s.permanent_address FROM Students s WHERE s.permanent_address_id != s.current_address_id;
SELECT s.first_name, s.last_name FROM Students s WHERE s.permanent_address_id = s.permanent_address_id AND s.permanent_address_id != s.current_address_id;
SELECT DISTINCT s.place_id, s.lines FROM Addresses s JOIN Students s ON s.address_id = s.current_address_id JOIN Student_Enrolment_Courses sc ON s.student_id = sc.student_course_id JOIN Courses c ON sc.course_id = c.course_id JOIN Departments d ON c.department_id = d.department_id JOIN Degree_Programs dp ON dp.department_id = d.department_id JOIN Sections s2 ON s2.section_id = s.section_id JOIN Semesters s3 ON s3.semester_id = s2.semester_id JOIN Student_Enrolment se ON se.student_id = s.student_id JOIN Transcripts t ON se.student_id = t.transcript_id JOIN Transcript_Contents tc ON tc.transcript_id = t.transcript_id JOIN Courses c2 ON tc.student_course_id = c2.course_id;
SELECT S.id, S.line_1, S.line_2 FROM Addresses S JOIN Student_Enrolment_Courses SC ON S.address_id = SC.student_enrolment_id JOIN Sections ON S.current_address_id = Sections.section_id JOIN Courses ON SC.course_id = Courses.course_id JOIN Degree_Programs ON Sections.course_id = Degree_Programs.department_id JOIN Departments ON Degree_Programs.department_id = Departments.department_id JOIN Students ON S.current_address_id = Students.current_address_id;
SELECT AVG(transcript_date) FROM Transcripts;
SELECT AVG(date_left) FROM Students;
SELECT S.date_left, S.first_name, S.last_name, S.cell_mobile_number, S.email_address, S.ssn FROM Students S JOIN Student_Enrolment_Courses SC ON S.student_id = SC.student_course_id JOIN Courses C ON SC.course_id = C.course_id JOIN Sections S1 ON S.section_id = S1.section_id JOIN Departments D ON S1.department_id = D.department_id JOIN Degree_Programs DP ON D.department_id = DP.department_id JOIN Transcripts T ON S1.semester_id = T.semester_id JOIN Transcript_Contents TC ON T.transcript_id = TC.transcript_id WHERE S.date_left IS NOT NULL;
SELECT MIN(transcript_date) AS earliest_date FROM Transcripts;
SELECT COUNT(*) FROM Students;
SELECT COUNT(*) FROM Students;
SELECT MAX(transcript_date) FROM Transcripts;
SELECT MAX(transcript_date) AS last_student_record_release_date FROM Transcripts;
SELECT DISTINCT student_enrolment_id, course_id FROM Student_Enrolment_Courses JOIN Courses ON Student_Enrolment_Courses.course_id = Courses.course_id GROUP BY course_id
SELECT MAX(course_id), MAX(semester_id) FROM Sections;
SELECT s.student_id, s.date_first_registered, s.date_left, s.date_first_registered, s.date_left FROM Students s WHERE s.date_first_registered IS NULL OR s.date_left IS NULL ORDER BY s.date_first_registered, s.date_left LIMIT 1;
SELECT student_id, date_first_registered, date_left FROM Students ORDER BY date_first_registered ASC LIMIT 1;
SELECT DISTINCT semester_name FROM Semesters INNER JOIN Students ON Students.student_id = Student_Enrolment_Courses.student_enrolment_id INNER JOIN Courses ON Student_Enrolment_Courses.course_id = Courses.course_id INNER JOIN Departments ON Student_Enrolment_Courses.degree_program_id = Degree_Programs.department_id INNER JOIN Degree_Programs ON Degree_Programs.department_id = Departments.department_id WHERE Degree_Programs.degree_summary_name = 'Master' AND Degree_Programs.degree_summary_name = 'Bachelor';
SELECT Students.student_id FROM Students INNER JOIN Student_Enrolment_Courses ON Student_Enrolment_Courses.course_id = Courses.course_id INNER JOIN Courses ON Courses.course_id = Student_Enrolment_Courses.course_id INNER JOIN Students ON Students.student_id = Student_Enrolment_Courses.student_enrolment_id INNER JOIN Degree_Programs ON Student_Enrolment_Courses.degree_program_id = Degree_Programs.degree_program_id INNER JOIN Departments ON Degree_Programs.department_id = Departments.department_id WHERE Courses.course_name IN ('Masters', 'Bachelors')
SELECT COUNT(DISTINCT Addresses.address_id) FROM Addresses;
SELECT DISTINCT address_id, city, state_province_county, country, other_address_details FROM Addresses;
SELECT s.first_name, s.middle_name, s.last_name, s.cell_mobile_number, s.email_address, s.ssn, s.date_first_registered, s.date_left, s.other_student_details FROM Students s ORDER BY s.last_name DESC;
SELECT s.first_name, s.last_name, s.middle_name, s.cell_mobile_number, s.email_address, s.ssn, s.date_first_registered, s.date_left, s.other_student_details FROM Students s ORDER BY s.first_name DESC, s.last_name ASC LIMIT 10;
SELECT DISTINCT section_name, section_description FROM Sections ORDER BY section_name
SELECT course_description FROM Courses WHERE section_name = 'h'
SELECT s.last_name, s.cell_mobile_number FROM Students s JOIN Addresses a ON s.permanent_address_id = a.address_id WHERE a.country = 'Haiti' OR s.cell_mobile_number = '09700166582';
SELECT s.first_name, s.last_name, s.cell_mobile_number, s.email_address, s.ssn FROM Students s JOIN Addresses a ON s.permanent_address_id = a.address_id WHERE a.country = 'Haiti' OR s.cell_mobile_number = '09700166582'
SELECT Title FROM Cartoon ORDER BY Title ASC;
SELECT Title FROM Cartoon ORDER BY Title ASC;
SELECT Cartoon.Directed_by FROM Cartoon JOIN TV_series ON Cartoon.Channel = TV_series.Channel WHERE Cartoon.Directed_by = 'Ben Jones';
SELECT Title, Directed_by FROM Cartoon JOIN TV_Channel ON Cartoon.Channel = TV_Channel.id WHERE Directed_by = 'Ben Jones' GROUP BY Title, Directed_by
SELECT COUNT(*) FROM TV_series WHERE Written_by = 'Joseph Kuhr'
SELECT COUNT(*) AS Number_of_Animations FROM Cartoon WHERE Written_by = 'Joseph Kuhr'
SELECT TV_series.id, TV_series.Series, TV_series.Air_Date, TV_series.Rating, TV_series.Channel, TV_series.Viewers_m, TV_series.Weekly_Rank, TV_series.Channel FROM TV_series JOIN TV_channel ON TV_series.Channel = TV_channel.id ORDER BY TV_series.Air_Date;
SELECT Title, Directed_by FROM Cartoon ORDER BY Air_Date;
