SELECT Title FROM Cartoon WHERE Directed_by = 'Ben Jones' OR Directed_by = 'Brandon Vietti' AND Title IS NOT NULL
SELECT Country, COUNT(TV_Channel.id) AS Number_of_TV_Channels FROM TV_Channel JOIN TV_series ON TV_Channel.Channel = TV_series.Channel GROUP BY Country ORDER BY Number_of_TV_Channels DESC;
SELECT TV_Channel.Country, COUNT(TV_Channel.id) AS Channel_Count FROM TV_Channel JOIN TV_series ON TV_series.Channel = TV_Channel.id GROUP BY TV_Channel.Country ORDER BY Channel_Count DESC LIMIT 1
SELECT COUNT(DISTINCT series_name), COUNT(DISTINCT Content) FROM TV_Channel;
SELECT COUNT(DISTINCT TV_Channel.Content) AS Content_count, COUNT(DISTINCT TV_Channel.Serial) AS Serial_count FROM TV_Channel;
SELECT Content FROM TV_Channel WHERE series_name = 'Sky Radio'
SELECT Content FROM TV_Channel INNER JOIN TV_series ON TV_Channel.id = TV_series.Channel;
SELECT TV_Channel.Package_Option FROM TV_Channel JOIN TV_series ON TV_Channel.id = TV_series.Channel JOIN Cartoon ON TV_Channel.Channel = Cartoon.Channel WHERE TV_series.Series_Name = 'Sky Radio'
SELECT TV_Channel.Package_Option FROM TV_Channel JOIN TV_series ON TV_Channel.Channel = TV_series.Channel WHERE TV_series.Series_name = 'Sky Radio' LIMIT 1
