SELECT owners.state, dogs.dog_id, treatments.treatment_type_code FROM Owners INNER JOIN Dogs ON Owners.owner_id = Dogs.owner_id INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id INNER JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code WHERE dogs.gender = 'Male' AND treatments.cost_of_treatment > 0;
SELECT Owners.state FROM Owners INNER JOIN Dogs ON Dogs.owner_id = Owners.owner_id INNER JOIN Professionals ON Dogs.owner_id = Professionals.professional_id INNER JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code INNER JOIN Dogs ON Treatments.dog_id = Dogs.dog_id;
SELECT AVG(Dogs.age) AS average_age FROM Dogs;
SELECT AVG(Dogs.age) FROM Dogs;
SELECT Dogs.owner_id, Owners.first_name, Owners.last_name, Dogs.cell_number FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Owners.state = 'Indiana' OR Dogs.dog_id IN (SELECT dog_id FROM Charges WHERE charge_type = 'medical' AND charge_amount > 2)
SELECT Owners.owner_id, Owners.last_name, Professionals.last_name FROM Owners JOIN Professionals ON Owners.owner_id = Professionals.owner_id WHERE Owners.state = 'Indiana' OR Professionals.cell_number IS NOT NULL AND Professionals.cell_number LIKE '%2' AND Professionals.cell_number LIKE '%4'
SELECT Dogs.name FROM Dogs WHERE Dogs.date_departed IS NULL OR Dogs.date_departed <= (SELECT MAX(date_of_treatment) FROM Treatments WHERE treatment_type_code = 'health-care') OR Dogs.date_departed IS NULL;
SELECT Dogs.name FROM Dogs INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id INNER JOIN Professionals ON Treatments.professional_id = Professionals.professional_id INNER JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code WHERE Treatments.cost_of_treatment > 1000;
SELECT DISTINCT o.first_name FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Professionals p ON d.owner_id = p.owner_id WHERE d.breed_code IS NULL OR d.size_code IS NULL OR d.name IS NULL OR d.professional_id IS NULL OR p.first_name IS NULL
SELECT Dogs.first_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Dogs.breed_code IS NULL OR Dogs.size_code IS NULL OR Dogs.name IS NULL OR Dogs.owner_id IS NULL OR Dogs.owner_id IS NOT NULL AND Dogs.first_name IS NOT NULL AND Dogs.first_name != 'dog'
