SELECT Dogs.owner_id, Dogs.name, Dogs.family_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id INNER JOIN Professionals ON Treatments.professional_id = Professionals.professional_id WHERE Dogs.dog_id IN (SELECT Dogs.dog_id FROM Dogs WHERE Dogs.dog_id IN (SELECT Dogs.dog_id FROM Dogs ORDER BY Dogs.age DESC LIMIT 1))
