SELECT o.owner_id, o.first_name, o.last_name, o.street, o.city, o.state, o.zip_code, o.email_address, o.home_phone, o.cell_number, d.name, d.age, d.date_of_birth, d.gender, d.weight, d.date_arrived, d.date_adopted, d.date_departed, t.cost_of_treatment FROM Owners o INNER JOIN Dogs d ON o.owner_id = d.owner_id INNER JOIN Treatments t ON d.dog_id = t.dog_id INNER JOIN Treatment_Types t1 ON t.treatment_type_code = t1.treatment_type_code INNER JOIN Professionals p ON t.professional_id = p.professional_id GROUP BY o.owner_id, o.first_name, o.last_name, o.street, o.city, o.state, o.zip_code, o.email_address, o.home_phone, o.cell_number, d.name, d.age, d.date_of_birth, d.gender, d.weight, d.date_arrived, d.date_adopted, d.date_departed, t.cost_of_treatment ORDER BY t.cost_of_treatment DESC;
SELECT Dogs.guardian_id, Dogs.family_name, Treatment_Types.treatment_type_description, Treatments.cost_of_treatment FROM Dogs JOIN Treatment_Types ON Dogs.breed_code = Treatment_Types.treatment_type_code JOIN Treatments ON Treatments.dog_id = Dogs.dog_id JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Treatments.cost_of_treatment ORDER BY Treatments.cost_of_treatment DESC LIMIT 1;
SELECT DISTINCT "cost_of_treatment" FROM Treatments JOIN Dogs ON Treatments.dog_id = Dogs.dog_id ORDER BY "cost_of_treatment" ASC LIMIT 1;
SELECT Dogs.name, Dogs.weight, Dogs.date_of_birth, Dogs.date_arrived, Dogs.date_departed, Professionals.first_name, Professionals.last_name, Professionals.email_address, Professionals.home_phone, Professionals.cell_number, Treatment_Types.treatment_type_description, Treatments.cost_of_treatment FROM Dogs JOIN Professionals ON Dogs.owner_id = Professionals.owner_id JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code JOIN Treatments ON Treatments.dog_id = Dogs.dog_id JOIN Sizes ON Dogs.size_code = Sizes.size_code JOIN Breeds ON Dogs.breed_code = Breeds.breed_code WHERE Treatments.cost_of_treatment < (SELECT MIN(cost_of_treatment) FROM Charges)
SELECT o.owner_id, t.zip_code FROM Owners o JOIN Treatments t ON o.owner_id = t.dog_id JOIN Dogs d ON d.owner_id = o.owner_id GROUP BY o.owner_id ORDER BY t.cost_of_treatment DESC LIMIT 1;
SELECT Dogs.owner_id, Dogs.zip_code, SUM(Dogs.date_departed) AS total_money_spent FROM Dogs JOIN Treatments ON Dogs.dog_id = Treatments.dog_id JOIN Owners ON Dogs.owner_id = Owners.owner_id GROUP BY Dogs.owner_id, Dogs.zip_code ORDER BY SUM(Dogs.date_departed) DESC;
SELECT Dogs.dog_id, Owners.cell_number FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Dogs.abandoned_yn = 'Y' AND Dogs.date_of_birth IS NOT NULL;
SELECT Dogs.id, Dogs.cell_number FROM Dogs INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id INNER JOIN Professionals ON Treatments.professional_id = Professionals.professional_id INNER JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code WHERE Treatments.treatment_type_code IN ('Health Care', 'Health Care') GROUP BY Dogs.id, Dogs.cell_number;
SELECT o.first_name, o.last_name FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Treatments t ON d.dog_id = t.dog_id JOIN Professionals p ON t.professional_id = p.professional_id WHERE t.cost_of_treatment < 100000 AND o.first_name != '' AND o.last_name != ''
SELECT DISTINCT o.first_name, o.last_name, d.name, d.age, d.date_of_birth, d.gender, d.date_departed FROM Owners o INNER JOIN Dogs d ON o.owner_id = d.owner_id INNER JOIN Treatments t ON d.dog_id = t.dog_id INNER JOIN Treatment_Types t2 ON t.treatment_type_code = t2.treatment_type_code INNER JOIN Charges c ON t.treatment_id = c.treatment_id WHERE c.charge_amount < (SELECT AVG(charge_amount) FROM Charges) GROUP BY o.first_name, o.last_name, d.name, d.age, d.date_of_birth, d.gender, d.date_departed;
SELECT Dogs.date_of_birth, Professionals.first_name FROM Dogs INNER JOIN Professionals ON Dogs.owner_id = Professionals.owner_id;
SELECT Dogs.date_of_birth, Professionals.first_name AS operating_veterinarian_given_name FROM Dogs INNER JOIN Professionals ON Dogs.owner_id = Professionals.owner_id;
SELECT Dogs.dog_id, Dogs.name, Dogs.weight, Dogs.date_of_birth, Dogs.date_arrived, Dogs.date_departed, Treatment_Types.treatment_type_description, Charges.charge_amount, Charges.charge_type FROM Dogs JOIN Treatment_Types ON Dogs.breed_code = Treatment_Types.treatment_type_code JOIN Charges ON Dogs.dog_id = Charges.charge_id WHERE Charges.charge_type = 'Health Care' AND Dogs.date_of_birth IS NOT NULL;
SELECT Dogs.name, Dogs.weight, Treatment_Types.treatment_type_description, Charges.charge_amount AS cost FROM Dogs INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id INNER JOIN Professionals ON Treatments.professional_id = Professionals.professional_id INNER JOIN Treatments ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code;
SELECT Dogs.first_name, Dogs.last_name, Sizes.size_code AS size_code FROM Dogs INNER JOIN Sizes ON Dogs.size_code = Sizes.size_code;
SELECT Dogs.first_name, Dogs.last_name, Dogs.size_code AS dog_size FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id;
SELECT Dogs.name, Owners.first_name, Owners.last_name FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id JOIN Treatments ON Dogs.dog_id = Treatments.dog_id JOIN Professionals ON Treatments.professional_id = Professionals.professional_id;
SELECT Dogs.name, Treatments.treatment_type_description FROM Dogs JOIN Treatments ON Dogs.dog_id = Treatments.dog_id JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code;
SELECT Dogs.name, Treatments.date_of_treatment FROM Dogs INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id;
SELECT Dogs.name, Treatments.date_of_treatment AS care_date FROM Dogs INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id WHERE Treatments.treatment_type_code = (SELECT treatment_type_code FROM Treatment_Types WHERE treatment_type_description = 'Rare') AND Treatments.cost_of_treatment IS NOT NULL;
SELECT Dogs.name, Owners.first_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Owners.state = 'Virginia' GROUP BY Dogs.name, Owners.first_name
SELECT Dogs.name, Owners.first_name, Owners.last_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Owners.state = 'Virginia' AND Dogs.abandoned_yn = 'N' AND Dogs.breed_code = Breeds.breed_code;
SELECT Dogs.date_departed, Dogs.date_arrived, Dogs.name, Dogs.gender, Dogs.date_of_birth, Dogs.weight, Dogs.date_of_birth, Dogs.date_departed FROM Dogs JOIN Treatments ON Dogs.dog_id = Treatments.dog_id JOIN Professionals ON Treatments.professional_id = Professionals.professional_id JOIN Breeds ON Dogs.breed_code = Breeds.breed_code JOIN Sizes ON Dogs.size_code = Sizes.size_code JOIN Owners ON Dogs.owner_id = Owners.owner_id;
SELECT Dogs.date_arrived, Dogs.date_departed, Professionals.first_name, Professionals.last_name FROM Dogs INNER JOIN Professionals ON Dogs.owner_id = Professionals.owner_id;
SELECT Dogs.name, Owners.last_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Dogs.age = (SELECT MIN(age) FROM Dogs)
SELECT Owners.last_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Dogs.age = (SELECT MIN(age) FROM Dogs)
SELECT Owners.email_address FROM Owners JOIN Dogs ON Dogs.owner_id = Owners.owner_id JOIN Breeds ON Dogs.breed_code = Breeds.breed_code JOIN Sizes ON Dogs.size_code = Sizes.size_code JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code JOIN Professionals ON Professionals.professional_id = Treatments.professional_id WHERE Owners.state = 'Hawaii' OR Owners.state = 'Wisconsin' LIMIT 10;
SELECT Owners.email_address FROM Owners INNER JOIN Dogs ON Dogs.owner_id = Owners.owner_id INNER JOIN Breeds ON Dogs.breed_code = Breeds.breed_code INNER JOIN Sizes ON Dogs.size_code = Sizes.size_code INNER JOIN Professionals ON Dogs.owner_id = Professionals.owner_id INNER JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code INNER JOIN Charges ON Treatments.treatment_type_code = Charges.charge_type INNER JOIN Sizes ON Dogs.size_code = Sizes.size_code INNER JOIN Treatments ON Treatments.dog_id = Dogs.dog_id INNER JOIN Professionals ON Professionals.professional_id = Treatments.professional_id WHERE Owners.state = 'Hawaii' OR Owners.state = 'Wisconsin' AND Treatments.date_of_treatment IS NOT NULL;
