SELECT AVG(Dogs.age) FROM Dogs;
SELECT AVG(Dogs.age) FROM Dogs;
SELECT Dogs.age, Treatments.cost_of_treatment FROM Dogs INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id ORDER BY Dogs.age DESC LIMIT 1;
