SELECT D.Breed_code, D.Size_code, D.Breed_name, D.Size_description, T.Treatment_type_code, T.Treatment_type_description FROM Dogs D JOIN Treatments T ON D.Dog_id = T.Dog_id JOIN Treatment_Types ON T.Treatment_type_code = T.Treatment_type_code JOIN Breeds ON D.Breed_code = Breeds.breed_code JOIN Sizes ON D.Size_code = Sizes.size_code;
