SELECT o.first_name, d.name, t.treatment_type_description, t.date_of_treatment, t.cost_of_treatment FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Treatments t ON d.dog_id = t.dog_id JOIN Treatment_Types t2 ON t.treatment_type_code = t2.treatment_type_code JOIN Breeds b ON d.breed_code = b.breed_code JOIN Sizes s ON d.size_code = s.size_code;
SELECT COUNT(*) FROM singer;
SELECT COUNT(*) AS count FROM singer;
SELECT Name FROM singer ORDER BY Net_Worth_Millions ASC;
SELECT Name FROM singer ORDER BY Net_Worth_Millions ASC
SELECT singer.Birth_Year, singer.Citizenship FROM singer;
SELECT Singer_ID, Birth_Year, Citizenship FROM singer;
SELECT Name FROM singer WHERE Citizenship != 'France'
SELECT Name FROM singer WHERE Citizenship != 'French'
SELECT Name FROM singer WHERE Birth_Year IN (1948, 1949)
SELECT Name FROM singer WHERE Birth_Year IN (1948, 1949)
SELECT Name FROM singer WHERE Net_Worth_Millions = (SELECT MAX(Net_Worth_Millions) FROM singer)
SELECT Name, Net_Worth_Millions FROM singer JOIN song ON song.Singer_ID = singer.Singer_ID ORDER BY Net_Worth_Millions DESC LIMIT 1
SELECT Singer_ID, Citizenship, COUNT(*) AS Number_of_Vocalists_per_Citizenship FROM singer GROUP BY Singer_ID, Citizenship
SELECT COUNT(*) AS Total_Musicians FROM singer;
SELECT DISTINCT singer.Name, singer.Citizenship FROM singer JOIN song ON singer.Singer_ID = song.Singer_ID ORDER BY singer.Citizenship DESC LIMIT 1;
SELECT DISTINCT singer.Citizenship FROM singer JOIN song ON singer.Singer_ID = song.Singer_ID;
SELECT DISTINCT Country, MAX(Song.Sales) AS Max_Net_Worth FROM singer JOIN song ON singer.Singer_ID = song.Singer_ID GROUP BY Country;
SELECT MAX(Singer.Net_Worth_Millions) AS Max_Net_Worth FROM singer;
SELECT singer.Name, song.Title FROM singer INNER JOIN song ON singer.Singer_ID = song.Singer_ID;
SELECT singer.Name, song.Singer_ID FROM singer INNER JOIN song ON song.Singer_ID = singer.Singer_ID;
SELECT DISTINCT singer.Name FROM singer INNER JOIN song ON singer.Singer_ID = song.Singer_ID WHERE song.Sales > 3000000
SELECT DISTINCT Name FROM singer WHERE Net_Worth_Millions > 300000;
SELECT Name FROM singer WHERE Singer_ID IN (SELECT Singer_ID FROM song WHERE Sales > 0)
SELECT Name FROM singer WHERE Singer_ID IN (SELECT Singer_ID FROM song WHERE Sales > 0 AND Song_Singer_ID = (SELECT Singer_ID FROM singer WHERE Name = 'Artist' OR Name = 'Song')
SELECT Singer.Name, SUM(song.Sales) AS Total_Sales FROM singer INNER JOIN song ON song.Singer_ID = singer.Singer_ID GROUP BY Singer.Name
SELECT DISTINCT singer.Name, SUM(song.Sales) AS Total_Sales FROM singer INNER JOIN song ON singer.Singer_ID = song.Singer_ID GROUP BY singer.Name
SELECT Name FROM singer WHERE Singer_ID NOT IN (SELECT Singer_ID FROM song WHERE Sales IS NULL)
SELECT Name FROM singer WHERE Singer_ID NOT IN (SELECT Singer_ID FROM song WHERE Sales IS NULL)
SELECT singer.Citizenship FROM singer JOIN song ON singer.Singer_ID = song.Singer_ID WHERE singer.Birth_Year < 1945 AND singer.Birth_Year > 1955;
SELECT DISTINCT s.Citizenship FROM singer s JOIN song s2 ON s.Singer_ID = s2.Singer_ID WHERE s2.Birth_Year BETWEEN 1945 AND 1955
SELECT COUNT(*) AS total_available_characteristics FROM Other_Property_Features;
SELECT DISTINCT feature_type_name FROM Ref_Feature_Types JOIN Other_Available_Features ON Other_Available_Features.feature_type_code = Ref_Feature_Types.feature_type_code;
SELECT Ref_Property_Types.property_type_description FROM Ref_Property_Types INNER JOIN Other_Property_Features ON Other_Property_Features.property_id = Properties.property_id INNER JOIN Other_Available_Features ON Other_Property_Features.feature_id = Other_Available_Features.feature_id WHERE Other_Available_Features.feature_type_code = Ref_Feature_Types.feature_type_code
SELECT property_name, property_type_code, property_address, room_count, vendor_requested_price, buyer_offered_price, agreed_selling_price, apt_feature_1, apt_feature_2, apt_feature_3, fld_feature_1, fld_feature_2, fld_feature_3, hse_feature_1, hse_feature_2, hse_feature_3, oth_feature_1, oth_feature_2, oth_feature_3, other_property_details FROM Properties WHERE property_type_code IN ('house', 'apartment') AND room_count > 1;
